//! Generated file layout, imports and formatting.

use std::collections::BTreeSet;

use proc_macro2::{Ident, TokenStream};
use quote::quote;

use crate::error::{Error, Result};
use crate::schema::{Document, Schema};
use crate::{AvroVersion, GeneratedFile, Language, Layout, RustTime, RustTypes, Settings};

use super::model::Model;
use super::render::Renderer;
use super::{helpers, naming, time};

/// Builds the header comment describing the generator version and settings.
fn header(settings: &Settings) -> Vec<String> {
    let derives = if settings.rust.derives.is_empty() {
        "none".to_owned()
    } else {
        settings.rust.derives.join(", ")
    };
    vec![
        format!(
            "Generated by avrox {} from an Avro schema. DO NOT EDIT.",
            env!("CARGO_PKG_VERSION")
        ),
        String::new(),
        "Settings used for generation:".to_owned(),
        String::new(),
        format!("- language: {}", language_name(settings.language)),
        format!(
            "- avro version: {}",
            avro_version_name(settings.avro_version)
        ),
        format!("- layout: {}", layout_name(settings.layout)),
        format!("- rust types: {}", rust_types_name(settings.rust.types)),
        format!("- rust time: {}", rust_time_name(settings.rust.time)),
        format!("- rust derives: {derives}"),
    ]
}

/// The inner doc attributes of the header, one per line.
fn header_docs(header: &[String]) -> Vec<TokenStream> {
    header
        .iter()
        .map(|line| {
            let line = format!(" {line}");
            quote! { #![doc = #line] }
        })
        .collect()
}

fn language_name(language: Language) -> &'static str {
    match language {
        Language::Rust => "rust",
    }
}

fn avro_version_name(version: AvroVersion) -> &'static str {
    match version {
        AvroVersion::V1_10 => "1.10",
        AvroVersion::V1_11 => "1.11",
        AvroVersion::V1_12 => "1.12",
    }
}

fn layout_name(layout: Layout) -> &'static str {
    match layout {
        Layout::SingleFile => "single",
        Layout::Module => "module",
    }
}

fn rust_types_name(types: RustTypes) -> &'static str {
    match types {
        RustTypes::ApacheAvro => "avro",
        RustTypes::Std => "std",
    }
}

fn rust_time_name(time: RustTime) -> &'static str {
    match time {
        RustTime::Primitives => "primitives",
        RustTime::StdTime => "std-time",
        RustTime::Chrono => "chrono",
    }
}

/// An import a generated file may need.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub(super) enum Import {
    Serde,
    ByteArray,
    ByteBuf,
    HashMap,
}

/// Per-file rendering state: which imports the file needs and which generated
/// types it references.
pub(super) struct FileContext {
    /// Rust name of the type defined in this file, if any. References to it
    /// are local and must not be imported.
    own_name: Option<String>,
    /// Names referenced from other files, collected for `use super::` imports.
    /// `None` when references stay local: single-file output and `mod.rs`,
    /// which re-exports every generated type instead.
    references: Option<BTreeSet<String>>,
    imports: BTreeSet<Import>,
    time_helpers: BTreeSet<time::Helper>,
}

impl FileContext {
    /// A file that contains everything it references locally.
    pub(super) fn local() -> Self {
        Self {
            own_name: None,
            references: None,
            imports: BTreeSet::new(),
            time_helpers: BTreeSet::new(),
        }
    }

    /// A file defining a single named type that may reference others.
    pub(super) fn child(own_name: String) -> Self {
        Self {
            own_name: Some(own_name),
            references: Some(BTreeSet::new()),
            imports: BTreeSet::new(),
            time_helpers: BTreeSet::new(),
        }
    }

    pub(super) fn needs(&mut self, import: Import) {
        self.imports.insert(import);
    }

    /// Records a generated time serde helper referenced by this file.
    pub(super) fn needs_time_helper(&mut self, helper: time::Helper) {
        self.time_helpers.insert(helper);
    }

    /// Records a generated helper referenced by this file.
    pub(super) fn reference(&mut self, name: &str) {
        if let Some(references) = &mut self.references {
            references.insert(name.to_owned());
        }
    }

    /// Records a generated type reference unless it refers to the type being
    /// defined in this file.
    pub(super) fn reference_unless_own(&mut self, name: &str) {
        if self.own_name.as_deref() != Some(name) {
            self.reference(name);
        }
    }
}

/// Renders the output files, or nothing if the schema defines no named types
/// and no unions.
pub(super) fn render(model: &Model<'_>, settings: &Settings) -> Result<Vec<GeneratedFile>> {
    if model.document.types.is_empty() && !model.has_named_union() {
        return Ok(Vec::new());
    }
    let renderer = Renderer::new(model);
    let header = header(settings);
    match settings.layout {
        Layout::SingleFile => render_single_file(model, &renderer, &header),
        Layout::Module => render_module(model, &renderer, &header),
    }
}

fn render_single_file(
    model: &Model<'_>,
    renderer: &Renderer<'_, '_>,
    header: &[String],
) -> Result<Vec<GeneratedFile>> {
    let mut context = FileContext::local();
    let mut items = Vec::new();
    if model.options.types == RustTypes::Std && helpers::uses_bytes(model.document) {
        items.push(helpers::bytes_type());
    }
    for wrapper in model.time.used_wrappers(model.document) {
        items.push(time::render(&wrapper));
    }
    for named in &model.document.types {
        items.push(renderer.render_named(named, &mut context)?);
    }
    for (id, union) in model.unions.iter().enumerate() {
        if union.name.is_some() {
            items.push(renderer.render_union_enum(id, &mut context)?);
        }
    }
    if let Some(module) = model.time.helper_module(&context.time_helpers) {
        items.insert(0, module);
    }
    let imports = imports(&context);
    assemble(output_path(model.document), header, &imports, &items).map(|file| vec![file])
}

/// Renders one file per named type plus a `mod.rs` declaring them,
/// re-exporting them and holding the generated union enums.
fn render_module(
    model: &Model<'_>,
    renderer: &Renderer<'_, '_>,
    header: &[String],
) -> Result<Vec<GeneratedFile>> {
    let mut files = Vec::new();
    let mut mod_decls = Vec::new();
    let mut re_exports = Vec::new();
    if model.options.types == RustTypes::Std && helpers::uses_bytes(model.document) {
        files.push(assemble(
            "bytes.rs".to_owned(),
            header,
            &[],
            &[helpers::bytes_type()],
        )?);
        mod_decls.push(quote! { pub mod bytes; });
        re_exports.push(quote! { pub use bytes::Bytes; });
    }
    let time_wrappers = model.time.used_wrappers(model.document);
    if !time_wrappers.is_empty() {
        let items: Vec<TokenStream> = time_wrappers.iter().map(time::render).collect();
        files.push(assemble("time.rs".to_owned(), header, &[], &items)?);
        mod_decls.push(quote! { pub mod time; });
        let idents: Vec<Ident> = time_wrappers
            .iter()
            .map(|wrapper| naming::make_ident(wrapper.name).0)
            .collect();
        if idents.len() == 1 {
            re_exports.push(quote! { pub use time::#(#idents)*; });
        } else {
            re_exports.push(quote! { pub use time::{#(#idents),*}; });
        }
    }
    for named in &model.document.types {
        let rust_name = model.type_names[named.name()].clone();
        let stem = naming::to_snake_case(&named.name().name);
        let (stem_ident, _) = naming::make_ident(&stem);
        let (type_ident, _) = naming::make_ident(&rust_name);
        let mut context = FileContext::child(rust_name);
        let item = renderer.render_named(named, &mut context)?;
        let imports = imports(&context);
        let mut items = Vec::new();
        if let Some(module) = model.time.helper_module(&context.time_helpers) {
            items.push(module);
        }
        items.push(item);
        files.push(assemble(format!("{stem}.rs"), header, &imports, &items)?);
        mod_decls.push(quote! { pub mod #stem_ident; });
        re_exports.push(quote! { pub use #stem_ident::#type_ident; });
    }
    let mut context = FileContext::local();
    let mut unions = Vec::new();
    for (id, union) in model.unions.iter().enumerate() {
        if union.name.is_some() {
            unions.push(renderer.render_union_enum(id, &mut context)?);
        }
    }
    let imports = imports(&context);
    let helper = model.time.helper_module(&context.time_helpers);
    let docs = header_docs(header);
    let tokens = quote! {
        #(#docs)*
        #(#mod_decls)*
        #(#imports)*
        #(#re_exports)*
        #helper
        #(#unions)*
    };
    let file = assemble_tokens("mod.rs".to_owned(), tokens)?;
    files.insert(0, file);
    Ok(files)
}

/// Assembles a generated file from its header, imports and items.
fn assemble(
    path: String,
    header: &[String],
    imports: &[TokenStream],
    items: &[TokenStream],
) -> Result<GeneratedFile> {
    let docs = header_docs(header);
    let tokens = quote! {
        #(#docs)*
        #(#imports)*
        #(#items)*
    };
    assemble_tokens(path, tokens)
}

fn assemble_tokens(path: String, tokens: TokenStream) -> Result<GeneratedFile> {
    let file = syn::parse2::<syn::File>(tokens)
        .map_err(|error| Error::Internal(format!("generated invalid Rust: {error}")))?;
    Ok(GeneratedFile {
        path,
        contents: prettyplease::unparse(&file),
    })
}

/// The `use` statements a generated file needs for its imports.
fn imports(context: &FileContext) -> Vec<TokenStream> {
    let mut uses = Vec::new();
    if context.imports.contains(&Import::Serde) {
        uses.push(quote! { use serde::{Deserialize, Serialize}; });
    }
    match (
        context.imports.contains(&Import::ByteArray),
        context.imports.contains(&Import::ByteBuf),
    ) {
        (true, true) => uses.push(quote! { use serde_bytes::{ByteArray, ByteBuf}; }),
        (true, false) => uses.push(quote! { use serde_bytes::ByteArray; }),
        (false, true) => uses.push(quote! { use serde_bytes::ByteBuf; }),
        (false, false) => {}
    }
    if context.imports.contains(&Import::HashMap) {
        uses.push(quote! { use std::collections::HashMap; });
    }
    if let Some(references) = &context.references
        && !references.is_empty()
    {
        let idents: Vec<Ident> = references
            .iter()
            .map(|name| naming::make_ident(name).0)
            .collect();
        uses.push(quote! { use super::{#(#idents),*}; });
    }
    uses
}

/// The output file path, derived from the root type name.
fn output_path(document: &Document) -> String {
    let stem = match &document.root {
        Schema::Record(name) | Schema::Enum(name) | Schema::Fixed(name) => {
            naming::to_snake_case(&name.name)
        }
        _ => "schema".to_owned(),
    };
    format!("{stem}.rs")
}
